      .map(item => transformItem(item))
      .sort((a, b) => complexSort(a, b));
  }, [rawData, filters]); // referential equality importa aquí

  return <Chart data={processedData} />;
}
```

---

### 🟡 5. Code splitting ausente

```jsx
