## Nivel 3: Virtualización con TanStack Virtual

Esta es la solución definitiva. TanStack Virtual es preferible a `react-window` porque funciona con tablas HTML reales (no divs), soporta filas de altura variable y tiene mejor integración con TypeScript.

```bash
npm install @tanstack/react-virtual
```

```tsx
import { useVirtualizer } from '@tanstack/react-virtual';
import { useRef, memo, useCallback } from 'react';

// Tipos explícitos: no any, no inferencia mágica
interface Metric {
  id: string;
  name: string;
  value: number;
  status: 'ok' | 'warning' | 'critical';
  category: string;
}

interface MetricsTableProps {
  data: Metric[];
  onMetricSelect?: (id: string) => void;
}

const ROW_HEIGHT = 48; // px — si tus filas tienen altura fija, úsala

const MetricsTable = ({ data, onMetricSelect }: MetricsTableProps) => {
  // Este ref va en el contenedor scrollable, NO en la tabla
  const containerRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: data.length,
    getScrollElement: () => containerRef.current,
    estimateSize: () => ROW_HEIGHT,
    overscan: 10, // filas extra arriba/abajo del viewport visible
    // overscan: cuántas filas renderizar fuera del viewport
    // Muy bajo (2-3): scroll con "parpadeo"
    // Muy alto (20+): pierdes beneficios de la virtualización
    // 10 es un buen punto de partida para tablas de métricas
  });

  const handleSelect = useCallback((id: string) => {
    onMetricSelect?.(id);
  }, [onMetricSelect]);

  const virtualItems = virtualizer.getVirtualItems();

  return (
    // Contenedor con altura fija y scroll — CRÍTICO
    <div
      ref={containerRef}
      style={{
        height: '600px',      // altura del viewport de la tabla
        overflow: 'auto',
        // Evita que el navegador recalcule layout en cada scroll
        willChange: 'transform',
        contain: 'strict',    // CSS containment: aísla el layout
      }}
    >
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead style={{ 
          position: 'sticky', 
          top: 0, 
          zIndex: 1,
          background: 'white' // necesario para que el sticky funcione visualmente
        }}>
          <tr>
            <th>Nombre</th>
            <th>Valor</th>
            <th>Estado</th>
            <th>Categoría</th>
          </tr>
        </thead>
        <tbody
          style={{
            // Este es el truco: tbody tiene la altura TOTAL de todas las filas
            // aunque solo renderizamos las visibles
            height: `${virtualizer.getTotalSize()}px`,
            position: 'relative',
          }}
        >
          {virtualItems.map((virtualRow) => {
            const metric = data[virtualRow.index];

            return (
              <MetricRow
                key={metric.id}
                metric={metric}
                onSelect={handleSelect}
                // Posicionamiento absoluto: cada fila se coloca
                // exactamente donde estaría si todas existieran en el DOM
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: `${virtualRow.size}px`,
                  transform: `translateY(${virtualRow.start}px)`,
                }}
              />
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

// La fila recibe el style de posicionamiento como prop
const MetricRow = memo(({ 
  metric, 
  onSelect, 
  style 
}: { 
  metric: Metric; 
  onSelect: (id: string) => void;
  style: React.CSSProperties;
}) => {
  return (
    <tr
      style={style}
      onClick={() => onSelect(metric.id)}
    >
      <td>{metric.name}</td>
      <td>{currencyFormatter.format(metric.value)}</td>
      <td><StatusBadge status={metric.status} /></td>
      <td>{metric.category}</td>
    </tr>
  );
});
```

---

## Nivel 4: Filas de altura variable (caso frecuente)

Si tus filas tienen contenido dinámico (descripciones, múltiples líneas):

```tsx
const MetricsTableVariableHeight = ({ data }: MetricsTableProps) => {
  const containerRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: data.length,
    getScrollElement: () => containerRef.current,
    estimateSize: () => 48, // estimación inicial — se corrige automáticamente
    // measureElement: el virtualizador mide el DOM real después del render
    // y actualiza las posiciones. Esto causa un pequeño "salto" inicial
    // que es aceptable y esperado.
  });

  return (
    <div ref={containerRef} style={{ height: '600px', overflow: 'auto' }}>
      <table style={{ width: '100%' }}>
        <tbody
          style={{
            height: `${virtualizer.getTotalSize()}px`,
            position: 'relative',
          }}
        >
          {virtualizer.getVirtualItems().map((virtualRow) => (
            <tr
              key={data[virtualRow.index].id}
              // ref aquí: el virtualizador mide este elemento en el DOM
              ref={virtualizer.measureElement}
              data-index={virtualRow.index} // necesario para measureElement
              style={{
                position: 'absolute',
                top: 0,
                transform: `translateY(${virtualRow.start}px)`,
                width: '100%',
              }}
            >
              <td>{data[virtualRow.index].name}</td>
              <td style={{ whiteSpace: 'pre-wrap' }}>
                {data[virtualRow.index].description}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};
```

