## Paso 3: Caché con stale-while-revalidate

Independientemente de la causa raíz, el nivel de fidelización **no cambia en tiempo real**. Una caché bien diseñada elimina la latencia del camino crítico para la mayoría de requests.

```typescript
interface CacheEntry<T> {
  data: T;
  fetchedAt: number;
  staleAt: number;      // cuando empieza a ser stale
  expiresAt: number;    // cuando se elimina definitivamente
}

class StaleWhileRevalidateCache<T> {
  private cache = new Map<string, CacheEntry<T>>();
  private revalidating = new Set<string>();

  constructor(
    private readonly ttlMs: number,        // tiempo hasta stale
    private readonly staleTtlMs: number,   // tiempo extra stale permitido
  ) {}

  async get(
    key: string,
    fetcher: () => Promise<T>,
  ): Promise<{ data: T; fromCache: boolean; stale: boolean }> {
    const now = Date.now();
    const entry = this.cache.get(key);

    // Cache miss: bloquea y espera
    if (!entry || now > entry.expiresAt) {
      const data = await fetcher();
      this.set(key, data, now);
      return { data, fromCache: false, stale: false };
    }

    // Cache hit fresco: devuelve inmediatamente
    if (now <= entry.staleAt) {
      return { data: entry.data, fromCache: true, stale: false };
    }

    // Stale: devuelve dato viejo y revalida en background
    if (!this.revalidating.has(key)) {
      this.revalidating.add(key);

      // Fire and forget - no bloquea la respuesta
      fetcher()
        .then((data) => {
          this.set(key, data, Date.now());
          logger.debug('loyalty_cache.revalidated', { key });
        })
        .catch((error) => {
          logger.error('loyalty_cache.revalidation_failed', { key, error });
          // Extiende el stale TTL para no dejar sin datos
          const staleEntry = this.cache.get(key);
          if (staleEntry) {
            staleEntry.expiresAt = Date.now() + this.staleTtlMs;
          }
        })
        .finally(() => {
          this.revalidating.delete(key);
        });
    }

    return { data: entry.data, fromCache: true, stale: true };
  }

  private set(key: string, data: T, now: number): void {
    this.cache.set(key, {
      data,
      fetchedAt: now,
      staleAt: now + this.ttlMs,
      expiresAt: now + this.ttlMs + this.staleTtlMs,
    });
  }

  invalidate(key: string): void {
    this.cache.delete(key);
  }
}

// Instancia: fresco 5min, stale aceptable hasta 1h
const loyaltyCache = new StaleWhileRevalidateCache<LoyaltyData>(
  5 * 60 * 1000,   // 5 minutos fresh
  60 * 60 * 1000,  // 1 hora stale
);

// Uso en el resolver
async function resolveLoyalty(userId: string): Promise<LoyaltyData> {
  const { data, fromCache, stale } = await loyaltyCache.get(
    `loyalty:${userId}`,
    () => callLoyaltyAPI(userId),
  );

  // Observabilidad del comportamiento de caché
  metrics.increment('loyalty_cache.access', {
    from_cache: fromCache.toString(),
    stale: stale.toString(),
  });

  return data;
}
```

