## Paso 4: Circuit breaker para resiliencia

Si el proveedor tiene degradación sostenida, no tiene sentido seguir esperando 3-4 segundos por request.

```typescript
import CircuitBreaker from 'opossum';

const loyaltyBreaker = new CircuitBreaker(callLoyaltyAPI, {
  timeout: 2000,           // falla si tarda más de 2s
  errorThresholdPercentage: 30,  // abre si >30% fallan
  resetTimeout: 30_000,    // intenta cerrar tras 30s
  volumeThreshold: 5,      // mínimo 5 llamadas para evaluar
});

loyaltyBreaker.on('open', () => {
  logger.error('loyalty_circuit_breaker.opened');
  metrics.increment('loyalty_circuit_breaker.state_change', { state: 'open' });
});

loyaltyBreaker.on('halfOpen', () => {
  logger.info('loyalty_circuit_breaker.half_open');
});

loyaltyBreaker.on('close', () => {
  logger.info('loyalty_circuit_breaker.closed');
  metrics.increment('loyalty_circuit_breaker.state_change', { state: 'closed' });
});

// Fallback: devuelve datos de caché aunque estén muy stale,
// o un valor degradado conocido
loyaltyBreaker.fallback((userId: string) => {
  const staleData = loyaltyCache.getStale(`loyalty:${userId}`);
  if (staleData) {
    logger.warn('loyalty.serving_stale_on_open_circuit', { userId });
    return staleData;
  }

  // Degradación conocida: nivel por defecto
  return { level: 'STANDARD', points: null, dataFreshness: 'unavailable' };
});
```

