### 4. Script de auditoría para detectar el problema antes del deploy

```javascript
// scripts/audit-dynamic-classes.js
const fs = require('fs');
const path = require('path');
const glob = require('glob');

const DYNAMIC_CLASS_PATTERNS = [
  /`[^`]*\$\{[^}]+\}[^`]*`/g,     // template literals con interpolación
  /['"][^'"]*'\s*\+\s*\w+/g,       // concatenación de strings
];

const files = glob.sync('./src/**/*.{js,jsx,ts,tsx}');
const warnings = [];

files.forEach(file => {
  const content = fs.readFileSync(file, 'utf8');

  DYNAMIC_CLASS_PATTERNS.forEach(pattern => {
    const matches = content.match(pattern);
    if (matches) {
      // Filtrar solo los que parecen nombres de clase CSS
      const classMatches = matches.filter(m => 
        /class|Class|className/.test(
          content.substring(Math.max(0, content.indexOf(m) - 50), content.indexOf(m))
        )
      );
      if (classMatches.length) {
        warnings.push({ file, matches: classMatches });
      }
    }
  });
});

if (warnings.length > 0) {
  console.warn('⚠️  Clases CSS dinámicas detectadas:');
  warnings.forEach(({ file, matches }) => {
    console.warn(`  ${file}:`);
    matches.forEach(m => console.warn(`    ${m}`));
  });
  process.exit(1); // romper el pipeline de CI
}

console.log('✅ No se detectaron clases dinámicas problemáticas');
```

